"""Generated grid: store-lane storm-gate parity, spike schedule. Cross-verified cell by cell at emit time.

Failure-Class: FC-projection-contention-chain-collides-inside-armed-storm-window

Each test re-drives its cell through the real boundary
(``drive_cell``) and compares the full observable freeze against the
literal the emit-time cross-verify produced; the independent model walk and
the emitter live outside the tree. Do not edit frozen literals by hand.
"""

from tests.unit.batch_projection_storm_gate_grid_harness import drive_cell


def _drive(monkeypatch, caplog, **params):
    return drive_cell(monkeypatch, caplog, **params)


def test_p_spi_n00000_f1_n00000_inf_en00000_f_abo(monkeypatch, caplog) -> None:
    assert _drive(
        monkeypatch,
        caplog,
        residual_schedule=[0.0],
        wave_wait=0.0,
        damper_mode='live',
        generation=5,
        log_mode='info',
        entry_wait=0.0,
        aborts=1,
        hostile_peek=False,
        deadline_margin=None,
        abort_kind='aborted',
        lane='store',
        store_label='batch_claim',
    ) == {
        'result': 'projected',
        'raised': None,
        'retry_after': 0.0,
        'body_calls': [1, 2],
        'sleeps': [0.15],
        'damper_slept': [],
        'events': [['consult', 'batch_claim', 0.0], ['peek', 'batch_claim', 0.0]],
        'note_success': [['batch_claim', 5]],
        'peek_count': 1,
        'consult_count': 1,
        'clients_consistent': True,
        'records': [],
    }


